/* Actual original-source/ATT/source projection fixtures; consumer tests measure real cfx. */
import fs from 'node:fs';import assert from 'node:assert/strict';import{createVecnaManagementEngine}from'./vecna-management-native.mjs';

const cases=[];
for(const phase of ['attached','unattuned','detached']){const f=createVecnaManagementEngine(),e=f.e;for(const [index,profile,part]of [[0,'current-eye','eye'],[1,'current-hand','hand']]){for(const [kind,body]of [['admit',{index,profile,facts:{actualPhysicalArtifactIdentityVerified:true,actualCurrentOriginalSourceVerified:true}}],['attachment',{physicalId:'vg-'+(index+1),facts:{actualPhysicalIdentityVerified:true,[part==='eye'?'actualEyeFusedIntoThisCharactersSocket':'actualHandGraftedOntoThisCharactersLeftStump']:true,printedRemovalConsequenceAcknowledged:true}}]]){const result=f.command(kind,body);assert.equal(result.ok,true);if(result.receipt)assert.equal(f.controller.acceptReceipt(result.receipt).ok,true);}}if(phase==='unattuned')e.c.B.inv[1].attuned=false;if(phase==='detached'){const r=f.command('detach',{physicalId:'vg-2',facts:{actualPhysicalRemovalVerified:true,printedRemovalConsequenceAcknowledged:true}});assert.equal(r.ok,true);}e.setC(e.project());assert.equal(e.c.vecnaGraftInitiativeAllowed(e.C,e.c.S),phase==='attached');assert.equal(e.C.inv.every(r=>r.eq===false),true);cases.push({phase,build:structuredClone(e.c.B),state:structuredClone(e.c.S),sheet:structuredClone(e.C),expectedAdvantage:phase==='attached'?1:0});}
fs.writeFileSync(new URL('./vecna-graft-fx.json',import.meta.url),JSON.stringify({provenance:'actual03 allocatedATT, original10w source and native12j/12zj; actual25t factual admit/attachment/detach commands; actualInitiativeCF/FXdice tested separately',cases},null,2)+'\n');console.log(cases.length+' real native Vecna source/ATT/history snapshots generated');
